const rows = function (n) { return $(n).all().map(function (i) { return i.json; }).filter(function (r) { return r && r.id; }); };
const kampanie = rows('API: kampanie');
const firmy = rows('API: firmy');
const wysylki = rows('API: dzisiejsze wysyłki');
const ust = {};
rows('API: ustawienia').forEach(function (r) { ust[r.klucz] = r.wartosc; });
const policz = function (lista, pole) { const o = {}; lista.forEach(function (x) { const k = x[pole] || 'brak'; o[k] = (o[k] || 0) + 1; }); return o; };
const teraz = DateTime.now().setZone('Europe/Warsaw');
const dzisISO = teraz.toFormat('yyyy-MM-dd');
const statusyAll = policz(firmy, 'status');
const limitDomyslny = parseInt(ust.limit_dzienny || '30', 10);
const SKUTECZNOSC_RESEARCHU = 0.6;
const dzialajace = function (k) { return k.status === 'aktywna' || k.status === 'wyczerpana'; };
const limit = kampanie.filter(dzialajace).reduce(function (sum, k) { return sum + (k.limit_dzienny || limitDomyslny); }, 0);
const dniRobocze = function (od, ile) { const wynik = []; let d = od.startOf('day'); while (wynik.length < ile) { if (d.weekday <= 5) wynik.push(d); d = d.plus({ days: 1 }); } return wynik; };
const pierwszyDzien = teraz.hour >= 15 || teraz.weekday > 5 ? teraz.plus({ days: 1 }) : teraz;
const kalendarz = dniRobocze(pierwszyDzien, 10);
const opisy = kampanie.slice().sort(function (a, b) { return String(b.data_start).localeCompare(String(a.data_start)); }).map(function (k) {
  const f = firmy.filter(function (x) { return x.kampania_id === k.kampania_id; });
  const s = policz(f, 'status');
  const lim = parseInt(k.limit_dzienny, 10) || limitDomyslny;
  let warianty = [];
  try { warianty = JSON.parse(k.warianty || '[]'); } catch (e) { warianty = []; }
  let szcz = {};
  try { szcz = JSON.parse(k.ocena_szczegoly || '{}'); } catch (e) { szcz = {}; }
  const szuka = k.status === 'aktywna' && ((k.wariant_idx || 0) < warianty.length || !k.osm_pobrane);
  const gotowe = s.gotowa || 0;
  const doSprawdzenia = (s.nowa || 0) + (s.w_researchu || 0) + (s.sprawdz_pozniej || 0);
  const pierwsze = f.filter(function (x) { return (x.etap || 0) >= 1; }).length;
  const follow = f.reduce(function (sum, x) { return sum + Math.max(0, Math.min(2, (x.etap || 0) - 1)); }, 0);
  const odp = (s.zainteresowany || 0) + (s.nie_teraz || 0) + (s.odmowa || 0);
  const koniec = k.data_koniec ? DateTime.fromISO(String(k.data_koniec)).setZone('Europe/Warsaw') : null;
  const start = k.data_start ? DateTime.fromISO(String(k.data_start)).setZone('Europe/Warsaw') : null;
  return {
    id: k.kampania_id, branza: k.branza, miasto: k.miasto, status: k.status, limit: lim, dni: k.dni || 0,
    start: start ? start.toISODate() : null, koniec: koniec ? koniec.toISODate() : null,
    dni_do_konca: koniec ? Math.max(0, Math.ceil(koniec.diff(teraz, 'days').days)) : 0,
    dzien: start ? Math.min(k.dni || 0, Math.max(1, Math.ceil(teraz.diff(start, 'days').days))) : 0,
    werdykt: k.werdykt, ocena: k.ocena_ai, uzasadnienie: k.uzasadnienie || '',
    plusy: (szcz.powody_za || []).slice(0, 5), minusy: (szcz.powody_przeciw || []).slice(0, 5),
    rynek_firm: szcz.szacunek_firm || null, rynek_z_mailem: szcz.szacunek_z_mailem || null,
    znalezione: f.length, gotowe: gotowe, do_sprawdzenia: doSprawdzenia, szuka: szuka,
    wyslane: pierwsze, follow: follow, odpowiedzi: odp, zainteresowani: s.zainteresowany || 0,
    nie_teraz: s.nie_teraz || 0, odmowy: s.odmowa || 0, odrzucone: s.odrzucona || 0, zle_maile: s.zly_mail || 0,
    _pula: gotowe + Math.round(doSprawdzenia * SKUTECZNOSC_RESEARCHU), _koniecDt: koniec
  };
});
const plan = kalendarz.map(function (d) { return { d: d, nowe: 0, follow: 0, uwagi: [] }; });
const indeks = {};
plan.forEach(function (p, i) { indeks[p.d.toFormat('yyyy-MM-dd')] = i; });
firmy.forEach(function (x) {
  if (x.status !== 'wyslana' || !x.data_nastepnego) return;
  let klucz = DateTime.fromISO(String(x.data_nastepnego)).setZone('Europe/Warsaw').toFormat('yyyy-MM-dd');
  if (klucz < plan[0].d.toFormat('yyyy-MM-dd')) klucz = plan[0].d.toFormat('yyyy-MM-dd');
  if (indeks[klucz] !== undefined) plan[indeks[klucz]].follow += 1;
});
opisy.forEach(function (o) {
  if (!dzialajace(o)) return;
  let pula = o._pula;
  plan.forEach(function (p, i) {
    if (o._koniecDt && p.d.startOf('day') > o._koniecDt.startOf('day')) return;
    const juz = p.d.toFormat('yyyy-MM-dd') === dzisISO ? wysylki.filter(function (w) { return w.typ === 'pierwszy' && w.kampania_id === o.id && w.status !== 'odbity'; }).length : 0;
    const ile = o.szuka ? Math.max(0, o.limit - juz) : Math.max(0, Math.min(o.limit - juz, pula));
    pula -= ile;
    p.nowe += ile;
    if (ile > 0) {
      if (i + 3 < plan.length) plan[i + 3].follow += Math.round(ile * 0.85);
      if (i + 7 < plan.length) plan[i + 7].follow += Math.round(ile * 0.8);
    }
    if (!o.szuka && pula <= 0 && !o.koniec_firm) { o.koniec_firm = p.d.toISODate(); p.uwagi.push('kończą się firmy: ' + o.branza + ' · ' + o.miasto); }
  });
  if (o._koniecDt && indeks[o._koniecDt.toFormat('yyyy-MM-dd')] !== undefined) plan[indeks[o._koniecDt.toFormat('yyyy-MM-dd')]].uwagi.push('ostatni dzień: ' + o.branza + ' · ' + o.miasto);
});
const ostrzezenia = [];
opisy.forEach(function (o) {
  if (!dzialajace(o)) return;
  if (o.koniec_firm) ostrzezenia.push({ typ: 'firmy', tekst: o.branza + ' · ' + o.miasto + ': firmy skończą się ok. ' + DateTime.fromISO(o.koniec_firm).toFormat('dd.MM') + '. Przygotuj nową kampanię.' });
  else if (o.dni_do_konca <= 3) ostrzezenia.push({ typ: 'koniec', tekst: o.branza + ' · ' + o.miasto + ': kampania kończy się ' + (o._koniecDt ? o._koniecDt.toFormat('dd.MM') : '') + '. Przygotuj następną.' });
});
if (!kampanie.filter(dzialajace).length) ostrzezenia.push({ typ: 'brak', tekst: 'Brak aktywnych kampanii, nic nie jest wysyłane. Utwórz nową kampanię.' });
if (ust.system_wstrzymany === 'tak') ostrzezenia.unshift({ typ: 'stop', tekst: 'Cały system jest wstrzymany. Nic nie jest szukane ani wysyłane.' });
opisy.forEach(function (o) { delete o._pula; delete o._koniecDt; });
return [{ json: {
  ok: true,
  czas: teraz.toISO(),
  system: { wstrzymany: ust.system_wstrzymany === 'tak', tryb_testowy: ust.tryb_testowy !== 'nie' },
  dzis: {
    nowe: wysylki.filter(function (w) { return w.status !== 'odbity' && w.typ === 'pierwszy'; }).length,
    follow: wysylki.filter(function (w) { return w.status !== 'odbity' && w.typ !== 'pierwszy'; }).length,
    zwroty: wysylki.filter(function (w) { return w.status === 'odbity'; }).length,
    limit: limit
  },
  liczniki: { gotowe: statusyAll.gotowa || 0, research: (statusyAll.nowa || 0) + (statusyAll.w_researchu || 0), zainteresowani: statusyAll.zainteresowany || 0, wyslane_lacznie: firmy.filter(function (x) { return (x.etap || 0) >= 1; }).length, odpowiedzi_lacznie: (statusyAll.zainteresowany || 0) + (statusyAll.nie_teraz || 0) + (statusyAll.odmowa || 0) },
  ostrzezenia: ostrzezenia,
  kampanie: opisy,
  harmonogram: plan.map(function (p) { return { data: p.d.toISODate(), nowe: p.nowe, follow: p.follow, uwagi: p.uwagi }; })
} }];

const b = $input.first().json.body || {};
const czysc = function (t) { return String(t || '').replace(/\s+/g, ' ').trim().slice(0, 60); };
const miastoS = czysc(b.miasto);
const miasto = miastoS ? miastoS.charAt(0).toUpperCase() + miastoS.slice(1) : '';
const branza = czysc(b.branza).toLowerCase();
let dni = parseInt(b.dni, 10); if (!dni || dni < 1) dni = 14; if (dni > 90) dni = 90;
let maile = parseInt(b.maile, 10); if (!maile || maile < 1) maile = 15; if (maile > 50) maile = 50;
