$('Sterowanie: ustawienia').all().forEach(function (i) { if (i.json && i.json.klucz) ust[i.json.klucz] = i.json.wartosc; });
const mapa = { wstrzymaj: 'wstrzymana', wznow: 'aktywna', zakoncz: 'zakonczona' };
