const rows = function (n) { return $(n).all().map(function (i) { return i.json; }).filter(function (r) { return r && r.id; }); };
const ust = {};
rows('Kolejka: ustawienia').forEach(function (r) { ust[r.klucz] = r.wartosc; });
const limitDomyslny = parseInt(ust.limit_dzienny || '30', 10);
const teraz = DateTime.now().setZone('Europe/Warsaw');
const dzisiaj = teraz.weekday <= 5 && teraz.hour < 15;
let dzien = teraz.startOf('day');
if (!dzisiaj) { dzien = dzien.plus({ days: 1 }); while (dzien.weekday > 5) dzien = dzien.plus({ days: 1 }); }
const wysylki = rows('Kolejka: dzisiejsze wysyłki').filter(function (w) { return w.typ === 'pierwszy' && w.status !== 'odbity'; });
const gotowe = rows('Kolejka: gotowe maile').filter(function (f) { return f.email && f.tresc; });
const kampanie = rows('Kolejka: kampanie').filter(function (k) { return k.status === 'aktywna' || k.status === 'wyczerpana'; });
const kampOut = kampanie.map(function (k) {
  const lim = parseInt(k.limit_dzienny, 10) || limitDomyslny;
